const DCAT=i=>i<14?"Лёгкие":i<28?"Глубже":"О нас";
const FREE_DECK=5;
function vDeck(){
  const x=X(), i=x.deck, locked=i>=FREE_DECK && !all();
  return `${iback()}<div class="stack-s"><h1>40 вопросов о близости</h1><p class="muted small">Задавайте по очереди и отвечайте честно. Можно пропустить любой вопрос — это нормально.</p></div>
  <div class="card i-deck"><span class="label">${DCAT(i)} · ${i+1} из ${DQ.length}</span>${locked?`<span class="pl-ico">${LOCK}</span><h3>Вопросы ${FREE_DECK+1}–${DQ.length} — в «Опора+ Всё»</h3><button class="btn" data-go="iplus">Подробнее</button>`:`<p class="i-q">${DQ[i]}</p>`}</div>
  <div class="row qz-row"><button class="btn quiet" id="dqPrev"${i?"":" disabled"}>← Назад</button><button class="btn" id="dqNext"${i<DQ.length-1?"":" disabled"}>Дальше →</button></div>
  <button class="linkbtn small" id="dqRand" style="align-self:center">Случайный вопрос</button>
  ${all()?"":`<p class="small muted">Бесплатно — первые ${FREE_DECK} вопросов.</p>`}`;
}
function bindDeck(){
  const set=v=>{ X().deck=Math.max(0,Math.min(DQ.length-1,v)); save(); render(); };
  const p=$("#dqPrev"); if(p) p.onclick=()=>set(X().deck-1);
  const n=$("#dqNext"); if(n) n.onclick=()=>set(X().deck+1);
  const r=$("#dqRand"); if(r) r.onclick=()=>{ const max=all()?DQ.length:FREE_DECK; let v; do v=Math.floor(Math.random()*max); while(v===X().deck && max>1); set(v); };
}

