let QS={i:0, ok:0, ans:null};
function vQuiz(){
  if(QS.i>=QZ.length){ const best=X().quiz.best;
    return `${iback()}<div class="card pass-card"><span class="label">Ваш результат</span><h2>${QS.ok} из ${QZ.length}</h2><p class="muted">${QS.ok>=17?"Вы отлично разбираетесь в теме.":QS.ok>=12?"Хороший результат — несколько мифов было коварными.":"Мифов вокруг близости много — теперь вы знаете больше."}</p>${best?`<p class="small muted">Лучший результат: ${best}</p>`:""}<button class="btn" id="qzAgain">Пройти ещё раз</button><button class="btn quiet" data-go="iknow">К статьям</button></div>`; }
  const q=QZ[QS.i], a=QS.ans;
  return `${iback()}<div class="stack-s"><h1>Мифы и факты</h1><p class="muted small">${QZ.length} утверждений о близости. Миф это или факт?</p></div>
  <div class="progress"><i style="width:${QS.i/QZ.length*100}%"></i></div>
  <div class="card"><span class="label">${QS.i+1} из ${QZ.length}</span><h3>${q[0]}</h3>
    ${a===null?`<div class="row qz-row"><button class="btn quiet" data-qa="0">Миф</button><button class="btn quiet" data-qa="1">Факт</button></div>`
    :`<p class="qz-res ${a===q[1]?"ok":"no"}"><strong>${a===q[1]?"Верно":"Не совсем"}: это ${q[1]?"факт":"миф"}</strong></p><p class="small">${q[2]}</p><button class="btn" id="qzNext">${QS.i<QZ.length-1?"Дальше":"Результат"}</button>`}
  </div>`;
}
function bindQuiz(){
  $$("[data-qa]").forEach(b=>b.onclick=()=>{ QS.ans=+b.dataset.qa; if(QS.ans===QZ[QS.i][1]) QS.ok++; render(); });
  const n=$("#qzNext"); if(n) n.onclick=()=>{ QS.i++; QS.ans=null; if(QS.i>=QZ.length){ const x=X(); if(QS.ok>x.quiz.best) x.quiz.best=QS.ok; save(); award("aware",10); } render(); window.scrollTo(0,0); };
  const a=$("#qzAgain"); if(a) a.onclick=()=>{ QS={i:0,ok:0,ans:null}; render(); };
}

